//! Cross-implementation vector tests.
//!
//! The `.tsv` files in `tests/data/` are generated by `reference/gen_vectors.py`
//! from an *independent* Python transcription of Reingold & Dershowitz, which
//! is itself cross-checked against CPython's proleptic Gregorian arithmetic,
//! against `convertdate.coptic` (same calendar structure, 276-year offset), and
//! — for the computus — against Meeus's Julian-calendar Easter algorithm.
//!
//! Two independent implementations agreeing on tens of thousands of
//! boundary-heavy dates is the strongest evidence this crate can offer that its
//! epoch, its leap phase and its epagomenal handling are right.

use ethiopic_calendar::bahire_hasab::{BahireHasab, Evangelist, MovableFeast};
use ethiopic_calendar::{EthiopianDate, GregorianDate, JulianDate, RataDie, Weekday};

const CONVERSIONS: &str = include_str!("data/conversions.tsv");
const COMPUTUS: &str = include_str!("data/computus.tsv");

fn rows(data: &str) -> impl Iterator<Item = Vec<&str>> {
    data.lines()
        .filter(|l| !l.starts_with('#') && !l.trim().is_empty())
        .map(|l| l.split('\t').collect())
}

fn i(f: &str) -> i64 {
    f.parse::<i64>()
        .unwrap_or_else(|_| panic!("not an integer: {f:?}"))
}

fn weekday_from_abbrev(s: &str) -> Weekday {
    match s {
        "Sun" => Weekday::Sunday,
        "Mon" => Weekday::Monday,
        "Tue" => Weekday::Tuesday,
        "Wed" => Weekday::Wednesday,
        "Thu" => Weekday::Thursday,
        "Fri" => Weekday::Friday,
        "Sat" => Weekday::Saturday,
        other => panic!("bad weekday {other:?}"),
    }
}

#[test]
fn conversion_vectors() {
    let mut checked = 0usize;
    for r in rows(CONVERSIONS) {
        assert_eq!(r.len(), 14, "malformed row: {r:?}");
        let rd = RataDie::new(i(r[0]));
        let jdn = i(r[1]);
        let (gy, gm, gd) = (i(r[2]) as i32, i(r[3]) as u8, i(r[4]) as u8);
        let (jy, jm, jd) = (i(r[5]) as i32, i(r[6]) as u8, i(r[7]) as u8);
        let (ey, em, ed) = (i(r[8]) as i32, i(r[9]) as u8, i(r[10]) as u8);
        let weekday = weekday_from_abbrev(r[11]);
        let doy = i(r[12]) as u16;
        let leap = i(r[13]) == 1;

        assert_eq!(rd.to_jdn(), jdn, "JDN offset at rd={rd}");
        assert_eq!(RataDie::from_jdn(jdn), rd);

        let g = GregorianDate::from_rata_die(rd).unwrap();
        assert_eq!(g.as_tuple(), (gy, gm, gd), "Gregorian at rd={rd}");
        assert_eq!(
            GregorianDate::from_ymd(gy, gm, gd).unwrap().to_rata_die(),
            rd
        );

        let j = JulianDate::from_rata_die(rd).unwrap();
        assert_eq!(j.as_tuple(), (jy, jm, jd), "Julian at rd={rd}");
        assert_eq!(JulianDate::from_ymd(jy, jm, jd).unwrap().to_rata_die(), rd);

        let e = EthiopianDate::from_rata_die(rd).unwrap();
        assert_eq!(e.as_tuple(), (ey, em, ed), "Ethiopic at rd={rd}");
        assert_eq!(
            EthiopianDate::from_ymd(ey, em, ed).unwrap().to_rata_die(),
            rd
        );
        assert_eq!(e.weekday(), weekday, "weekday at rd={rd}");
        assert_eq!(e.day_of_year(), doy, "day of year at rd={rd}");
        assert_eq!(e.is_leap_year(), leap, "leap flag at rd={rd}");

        // Direct calendar-to-calendar paths must agree with the pivot.
        assert_eq!(e.to_gregorian(), g);
        assert_eq!(EthiopianDate::from_gregorian(g).unwrap(), e);
        assert_eq!(e.to_julian().unwrap(), j);
        assert_eq!(EthiopianDate::from_julian(j).unwrap(), e);

        checked += 1;
    }
    assert!(checked > 20_000, "expected a large corpus, got {checked}");
}

#[test]
fn epagomenal_days_are_covered_by_the_corpus() {
    // Guards the generator: a corpus that silently stopped emitting Ṗagumēn 6
    // would make the headline bug class untested.
    let mut pagume6 = 0;
    for r in rows(CONVERSIONS) {
        if i(r[9]) == 13 && i(r[10]) == 6 {
            pagume6 += 1;
        }
    }
    assert!(pagume6 > 500, "only {pagume6} leap-day vectors");
}

#[test]
fn computus_vectors() {
    let mut checked = 0usize;
    for r in rows(COMPUTUS) {
        assert_eq!(r.len(), 12, "malformed row: {r:?}");
        let year = i(r[0]) as i32;
        let bh = BahireHasab::new(year).unwrap();
        assert_eq!(bh.amete_alem(), i(r[1]), "amete alem {year}");
        assert_eq!(i64::from(bh.medeb()), i(r[2]), "medeb {year}");
        assert_eq!(i64::from(bh.wenber()), i(r[3]), "wenber {year}");
        assert_eq!(i64::from(bh.abektie()), i(r[4]), "abektie {year}");
        assert_eq!(i64::from(bh.metqi()), i(r[5]), "metqi {year}");
        assert_eq!(
            (i64::from(bh.beale_metqi().month()), i64::from(bh.beale_metqi().day())),
            (i(r[6]), i(r[7])),
            "beale metqi {year}"
        );
        assert_eq!(bh.mebaja_hamer(), i(r[8]), "mebaja hamer {year}");
        assert_eq!(
            bh.feast(MovableFeast::Nineveh).unwrap().to_rata_die().get(),
            i(r[9]),
            "nineveh {year}"
        );
        assert_eq!(
            bh.feast(MovableFeast::Tinsae).unwrap().to_rata_die().get(),
            i(r[10]),
            "fasika {year}"
        );
        let expected_evangelist = match i(r[11]) {
            0 => Evangelist::Yohannes,
            1 => Evangelist::Matewos,
            2 => Evangelist::Marqos,
            _ => Evangelist::Luqas,
        };
        assert_eq!(bh.evangelist(), expected_evangelist, "evangelist {year}");
        checked += 1;
    }
    assert_eq!(checked, 3000);
}

/// Regression guard for the two bugs found in published implementations while
/// this crate was written; see `docs/PRIOR-ART.md`.
#[test]
fn known_bugs_in_other_implementations_are_not_reproduced() {
    // `convertdate.coptic.from_jd` returns (year+1, month 0, day 30) for the
    // sixth epagomenal day. The equivalent Ethiopic date must be 13/6.
    let rd = RataDie::new(627_738);
    let e = EthiopianDate::from_rata_die(rd).unwrap();
    assert_eq!(e.as_tuple(), (1711, 13, 6));
    assert_eq!(e.month(), 13);
    assert!(e.day() <= e.days_in_month());

    // The `ethiopian_date` PyPI package is one day out before 1900 because it
    // mishandles the Gregorian century rule: 1901-01-01 is Taḫśaś 23, not 24.
    let g = GregorianDate::from_ymd(1901, 1, 1).unwrap();
    assert_eq!(
        EthiopianDate::from_gregorian(g).unwrap().as_tuple(),
        (1893, 4, 23)
    );

    // ...and it cannot represent Ṗagumēn at all, because it returns a
    // `datetime.date`. 1900-09-06 is Ṗagumēn 1, 1892.
    let g = GregorianDate::from_ymd(1900, 9, 6).unwrap();
    assert_eq!(
        EthiopianDate::from_gregorian(g).unwrap().as_tuple(),
        (1892, 13, 1)
    );
}
